content.text:
        case "$line" in
            *:OK) pass "${line%:OK}" ;;
            *:FAIL) fail "$line" ;;
            DONE) saw_done=1 ;;
        esac
    done < "$out"
    if [ "$saw_done" = "1" ]; then
        pass "cp-driver-completed"
    else
        fail "cp-driver-completed:FAIL (driver aborted early)" "$(tail -5 "$out" 2>/dev/null)"
    fi

    rm -f "$drv" "$out"
}

